// Independent conventional stock-GGML FULL LAYER graph; no candidate stage or
// streaming projector is compiled here. Same defined inputs/state contract only.
#include "common.h"
using namespace a109;
namespace {
void execute(const Config&cfg,const State&old,Captures&out){Backend b;Workspace work;Context c;auto*ctx=c.p;
 auto*x=ggml_new_tensor_2d(ctx,GGML_TYPE_F32,H,1);auto*x0=ggml_new_tensor_2d(ctx,GGML_TYPE_F32,H,1);auto*normw=ggml_new_tensor_1d(ctx,GGML_TYPE_F32,H);auto*postw=ggml_new_tensor_1d(ctx,GGML_TYPE_F32,H);auto*qw=ggml_new_tensor_2d(ctx,GGML_TYPE_Q4_K,H,Q);auto*kw=ggml_new_tensor_2d(ctx,GGML_TYPE_Q8_0,H,K);auto*vw=ggml_new_tensor_2d(ctx,GGML_TYPE_Q8_0,H,K);auto*gw=ggml_new_tensor_2d(ctx,GGML_TYPE_Q4_K,H,Q);auto*ow=ggml_new_tensor_2d(ctx,GGML_TYPE_Q6_K,Q,H);auto*qgamma=ggml_new_tensor_1d(ctx,GGML_TYPE_F32,D);auto*kgamma=ggml_new_tensor_1d(ctx,GGML_TYPE_F32,D);auto*lambda=ggml_new_tensor_1d(ctx,GGML_TYPE_F32,1);auto*position=ggml_new_tensor_1d(ctx,GGML_TYPE_I32,1);auto*m=ggml_new_tensor_2d(ctx,GGML_TYPE_F32,cfg.slots,1);auto*keys=ggml_new_tensor_3d(ctx,GGML_TYPE_F16,D,NKV,cfg.slots);auto*values=ggml_new_tensor_3d(ctx,GGML_TYPE_F16,D,NKV,cfg.slots);
 auto*a=ggml_mul(ctx,ggml_rms_norm(ctx,x,1e-6f),normw);auto*qraw=ggml_mul_mat(ctx,qw,a);auto*kraw=ggml_mul_mat(ctx,kw,a);auto*vi=ggml_add(ctx,x0,ggml_mul(ctx,ggml_sub(ctx,a,x0),ggml_sigmoid(ctx,lambda)));auto*vraw=ggml_mul_mat(ctx,vw,vi);
 auto*qn=ggml_mul(ctx,ggml_rms_norm(ctx,ggml_reshape_3d(ctx,qraw,D,NH,1),1e-6f),qgamma);auto*kn=ggml_mul(ctx,ggml_rms_norm(ctx,ggml_reshape_3d(ctx,kraw,D,NKV,1),1e-6f),kgamma);auto*q=qn;auto*k=kn;
 if(cfg.sliding()){q=ggml_rope_ext(ctx,qn,position,nullptr,128,GGML_ROPE_TYPE_NEOX,2097152,10000.f,1,0,1,32,1);k=ggml_rope_ext(ctx,kn,position,nullptr,128,GGML_ROPE_TYPE_NEOX,2097152,10000.f,1,0,1,32,1);}
 auto*ks=ggml_view_3d(ctx,keys,D,NKV,1,keys->nb[1],keys->nb[2],old.position*keys->nb[2]);auto*vs=ggml_view_3d(ctx,values,D,NKV,1,values->nb[1],values->nb[2],old.position*values->nb[2]);auto*graph=ggml_new_graph_custom(ctx,128,false);ggml_build_forward_expand(graph,ggml_cpy(ctx,k,ks));ggml_build_forward_expand(graph,ggml_cpy(ctx,ggml_reshape_3d(ctx,vraw,D,NKV,1),vs));
 auto*scores=ggml_mul_mat(ctx,ggml_permute(ctx,keys,0,2,1,3),ggml_permute(ctx,q,0,2,1,3));need(ggml_prec_set_acc(scores,GGML_PREC_F32),"stock F32 score accumulation");auto*prob=ggml_soft_max_ext(ctx,scores,m,1.f/std::sqrt(128.f),0);auto*vp=ggml_cont(ctx,ggml_transpose(ctx,ggml_permute(ctx,values,0,2,1,3)));auto*att=ggml_cont_2d(ctx,ggml_permute(ctx,ggml_mul_mat(ctx,vp,prob),0,2,1,3),Q,1);auto*gp=ggml_mul_mat(ctx,gw,a);auto*gated=ggml_mul(ctx,att,ggml_sigmoid(ctx,gp));auto*op=ggml_mul_mat(ctx,ow,gated);auto*post=ggml_mul(ctx,ggml_rms_norm(ctx,op,1e-6f),postw);auto*attn_residual=ggml_add(ctx,post,x);
 auto*ffnw=ggml_new_tensor_1d(ctx,GGML_TYPE_F32,H);auto*ffnpostw=ggml_new_tensor_1d(ctx,GGML_TYPE_F32,H);
 auto*fgw=ggml_new_tensor_2d(ctx,ggml_type(cfg.layer<15||cfg.layer>=65?13:12),H,fixture107::F);auto*fuw=ggml_new_tensor_2d(ctx,ggml_type(cfg.layer<15||cfg.layer>=65?13:12),H,fixture107::F);auto*fdw=ggml_new_tensor_2d(ctx,ggml_type(cfg.layer<15||cfg.layer>=65?13:12),fixture107::F,H);
 auto*fa=ggml_mul(ctx,ggml_rms_norm(ctx,attn_residual,1e-6f),ffnw);auto*fg=ggml_mul_mat(ctx,fgw,fa);auto*fu=ggml_mul_mat(ctx,fuw,fa);auto*fs=ggml_swiglu_clamp(ctx,fg,fu,20.f);auto*fd=ggml_mul_mat(ctx,fdw,fs);auto*fp=ggml_mul(ctx,ggml_rms_norm(ctx,fd,1e-6f),ffnpostw);auto*final=ggml_add(ctx,fp,attn_residual);
 std::vector<std::pair<std::string,ggml_tensor*>>taps={{"input-norm",a},{"q-projection",qraw},{"k-projection",kraw},{"value-input",vi},{"v-current",vraw},{"q-norm",qn},{"k-norm",kn},{"q-current",q},{"k-current",k},{"scores",scores},{"probabilities",prob},{"attention",att},{"gate-projection",gp},{"gated",gated},{"output-projection",op},{"post-norm",post},{"attention-residual",attn_residual},{"ffn-input-norm",fa},{"ffn-gate",fg},{"ffn-up",fu},{"ffn-active",fs},{"ffn-down",fd},{"ffn-post-norm",fp},{"final",final}};for(auto&t:taps)ggml_set_output(t.second);ggml_build_forward_expand(graph,final);
 size_t weights=ggml_nbytes(qw)+ggml_nbytes(kw)+ggml_nbytes(vw)+ggml_nbytes(gw)+ggml_nbytes(ow)+ggml_nbytes(fgw)+ggml_nbytes(fuw)+ggml_nbytes(fdw);Buffer buffer(ctx,b.p,weights);need(buffer.bytes<560*1024*1024,"reference attention bound");
 auto fill=[&](const char*name,ggml_tensor*t,int id,int columns,int rows){InputBlocks source(t->type,id);Digest hash;std::vector<uint8_t>row(ggml_row_size(t->type,columns));for(int r=0;r<rows;++r){source.row(r,columns,row.data());hash.add(row.data(),row.size());ggml_backend_tensor_set(t,row.data(),size_t(r)*row.size(),row.size());}weight_identity(name,hash,ggml_nbytes(t));};
 fill("q",qw,0,H,Q);fill("k",kw,1,H,K);fill("v",vw,2,H,K);fill("gate",gw,3,H,Q);fill("output",ow,4,Q,H);fill("ffn-gate",fgw,0,H,fixture107::F);fill("ffn-up",fuw,1,H,fixture107::F);fill("ffn-down",fdw,2,fixture107::F,H);set(ffnw,gamma(H,0));set(ffnpostw,gamma(H,1));set(x,supplied("input.f32"));set(x0,supplied("original.f32"));set(normw,gamma(H,0));set(postw,gamma(H,1));set(qgamma,gamma(D,1));set(kgamma,gamma(D,0));set(m,mask(cfg,old.position));float l=-.375f;ggml_backend_tensor_set(lambda,&l,0,4);ggml_backend_tensor_set(position,&old.position,0,4);ggml_backend_tensor_set(keys,old.key.data(),0,old.key.size()*2);ggml_backend_tensor_set(values,old.value.data(),0,old.value.size()*2);
 auto plan=work.plan(graph);mark("stock-attention.live",plan.work_size,Context::bytes,ggml_used_mem(ctx));need(ggml_graph_compute(graph,&plan)==GGML_STATUS_SUCCESS,"independent stock attention compute");for(auto&t:taps)get(out,t.first,t.second);auto masks=mask(cfg,old.position);raw(out,"mask.f32",masks.data(),masks.size()*4);
 State next=old;ggml_backend_tensor_get(keys,next.key.data(),0,next.key.size()*2);ggml_backend_tensor_get(values,next.value.data(),0,next.value.size()*2);++next.position;if(cfg.layer%5!=4){int expired=std::max(0,next.position-1024);for(int p=0;p<expired;++p)for(int j=0;j<K;++j){next.key[size_t(p)*K+j]=0;next.value[size_t(p)*K+j]=0;}}checkpoint(out,cfg,next);state_record(cfg,next,"next");
}
}
int main(int argc,char**argv)try{auto args=admit(argc,argv);need(std::string(argv[7])=="none","reference has no fault override");mark("before");{Captures out(0);execute(args.first,*authoritative,out);out.publish();}need(identity(*active_config,*authoritative)==before_state,"reference authoritative state changed");mark("after-cleanup");summary();return 0;}catch(const std::exception&e){return failed(e);}
